<?php require 'header.php'; $db=db_load(); $id=get('id'); $patient_id=get('patient_id'); $a=$id?find_item($db['appointments'],$id):null; if(!$a&&$patient_id){$a=['id'=>'','number'=>next_number($db['appointments'],'APT-'),'patient_id'=>$patient_id,'date'=>'','time'=>'','status'=>'Scheduled','amount'=>0,'medicine'=>'','instructions'=>'','next_date'=>'','created_at'=>now_iso()];} if(!$a) redirect('appointments.php'); if($_SERVER['REQUEST_METHOD']==='POST'){ $newNext=post('next_date'); foreach($db['appointments'] as &$x){if($x['id']===$a['id']){$x=array_merge($x,['date'=>post('date'),'time'=>post('time'),'status'=>post('status'),'amount'=>(float)post('amount'),'medicine'=>trim(post('medicine')),'instructions'=>trim(post('instructions')),'next_date'=>$newNext]);}}unset($x); if(!$a['id']) $db['appointments'][]=$a; db_save($db); redirect('patient-view.php?id='.urlencode($a['patient_id'])); } $p=find_item($db['patients'],$a['patient_id']); ?><div class="admin-top"><h1>Appointment <?=e($a['number'])?></h1><a class="btn btn-outline" href="patient-view.php?id=<?=e($a['patient_id'])?>">Back to Patient</a></div><div class="form-card"><p><b>Patient:</b> <?=e($p['name']??'-')?> (<?=e($p['number']??'-')?>)</p><form method="post"><div class="form-grid"><div class="field"><label>Appointment Date</label><input required type="date" name="date" value="<?=e($a['date'])?>"></div><div class="field"><label>Time</label><input required type="time" name="time" value="<?=e($a['time'])?>"></div><div class="field"><label>Status</label><select name="status"><?php foreach(['Scheduled','Confirmed','Completed','Cancelled','No Show'] as $st): ?><option <?=$a['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach; ?></select></div><div class="field"><label>Amount Paid</label><input type="number" step="0.01" name="amount" value="<?=e($a['amount'])?>"></div><div class="field full"><label>Medicine</label><textarea name="medicine" rows="4" placeholder="Add medicine when appointment is completed..."><?=e($a['medicine'])?></textarea></div><div class="field full"><label>Instructions</label><textarea name="instructions" rows="4" placeholder="Dosage, precautions, follow-up instructions..."><?=e($a['instructions'])?></textarea></div><div class="field"><label>Next Appointment Date</label><input type="date" name="next_date" value="<?=e($a['next_date'])?>"></div><div class="field" style="justify-content:end"><button class="btn">Save Appointment</button></div></div></form></div><?php require 'footer.php'; ?>
